-- SEION headless render for ardour9-lua (no GUI).
--
-- usage: ardour9-lua render_job.lua <session_dir> <session_name> <job.lua>
--
-- The session must be a copy of the seed session (one MIDI track + one MIDI
-- region per role, see build_seed_session.lua). The job file is generated by
-- seion_ardour and returns:
--   { bpm, length_beats, tail_seconds, export_dir, stems,
--     tracks = { <role> = { {start_beats, length_beats, note, velocity, channel}, ... } } }
-- Progress lines go to <export_dir>/render.log so a crash still leaves a trace.

local session_dir, session_name, job_path = arg[1], arg[2], arg[3]
local job = dofile(job_path)
local WAV_PRESET = "75969a1c-3133-4694-864b-a1fa50e43348" -- "WAV @ session-rate"

local logf = io.open(job.export_dir .. "/render.log", "w")
local function log(...)
	local t = {}
	for i = 1, select("#", ...) do t[#t + 1] = tostring(select(i, ...)) end
	logf:write(table.concat(t, "\t"), "\n")
	logf:flush()
end

local function beats(x)
	return Temporal.Beats.from_double(x)
end

-- GUI import names tracks "<role>-1-t1"; the role is what the job keys on.
local function role_of(track)
	return track:name():match("^(.-)%-%d+%-t%d+$") or track:name()
end

log("load", session_dir, session_name)
assert(load_session(session_dir, session_name), "load_session failed")

local tm = Temporal.TempoMap.write_copy()
tm:set_tempo(Temporal.Tempo(job.bpm, job.bpm, 4), Temporal.timepos_t(0))
Temporal.TempoMap.update(tm)
log("tempo", job.bpm)

local preroll = job.preroll_beats or 0
local length = Temporal.timecnt_t.from_ticks(beats(preroll + job.length_beats):to_ticks())

local function db_to_coeff(db)
	return 10 ^ (db / 20)
end

for t in Session:get_tracks():iter() do
	local role = role_of(t)
	local notes = job.tracks[role] or {}
	local gain = (job.gains_db or {})[role] or 0
	t:gain_control():set_value(db_to_coeff(gain), PBD.GroupControlDisposition.NoGroup)
	for r in t:to_track():playlist():region_list():iter() do
		local mr = r:to_midiregion()
		if not mr:isnil() then
			local model = mr:model()
			local cmd = model:new_note_diff_command("SEION render")
			for n in ARDOUR.LuaAPI.note_list(model):iter() do cmd:remove(n) end
			for _, n in ipairs(notes) do
				cmd:add(ARDOUR.LuaAPI.new_noteptr(n[5], beats(preroll + n[1]), beats(n[2]), n[3], n[4]))
			end
			model:apply_diff_command_as_commit(Session, cmd)
			r:set_length(length)
		end
	end
	log("track", role, "notes", #notes, "gain_db", gain)
end

local master = Session:master_out()
master:gain_control():set_value(db_to_coeff(job.master_gain_db or 0), PBD.GroupControlDisposition.NoGroup)

-- DC blocker / sub-sonic cleanup on the master (some Surge patches carry DC offset).
if (job.master_highpass_hz or 0) > 0 then
	local hp = ARDOUR.LuaAPI.new_luaproc(Session, "ACE High/Low Pass Filter")
	if not hp:isnil() then
		master:add_processor_by_index(hp, 0, nil, true)
		ARDOUR.LuaAPI.set_processor_param(hp, 0, 2) -- high pass 24 dB/oct
		ARDOUR.LuaAPI.set_processor_param(hp, 1, job.master_highpass_hz)
		ARDOUR.LuaAPI.set_processor_param(hp, 3, 0) -- low pass off
		log("master highpass", job.master_highpass_hz)
	end
end

local sr = Session:nominal_sample_rate()
local start_sample = math.floor(preroll * 60 / job.bpm * sr)
local end_sample = start_sample + math.floor((job.length_beats * 60 / job.bpm + job.tail_seconds) * sr)
Session:maybe_update_session_range(Temporal.timepos_t(0), Temporal.timepos_t(end_sample))

local function export(name)
	local e = Session:simple_export()
	e:set_preset(WAV_PRESET)
	e:set_folder(job.export_dir)
	e:set_name(name)
	e:set_range(start_sample, end_sample)
	local ok = e:run_export()
	log("export", name, ok)
	return ok
end

export("master")

if job.stems then
	local tracks = {}
	for t in Session:get_tracks():iter() do tracks[#tracks + 1] = t end
	for _, solo in ipairs(tracks) do
		if job.tracks[role_of(solo)] then
			for _, t in ipairs(tracks) do
				t:mute_control():set_value(t:name() == solo:name() and 0 or 1, PBD.GroupControlDisposition.NoGroup)
			end
			export("stem_" .. role_of(solo))
		end
	end
	for _, t in ipairs(tracks) do
		t:mute_control():set_value(0, PBD.GroupControlDisposition.NoGroup)
	end
end

Session:save_state("", false, false, false, false, false)
close_session()
log("done")
